enum Phase { Idle = "idle", Loading = "loading", Success = "success", Failure = "failure" }

type Action = "fetch" | "resolve" | "reject" | "reset"

function reduce(phase: Phase, action: Action): Phase {
    switch (phase) {
        case Phase.Idle:
            return action === "fetch" ? Phase.Loading : phase
        case Phase.Loading:
            if (action === "resolve") return Phase.Success
            if (action === "reject") return Phase.Failure
            return phase
        default:
            return action === "reset" ? Phase.Idle : phase
    }
}

let phase = Phase.Idle
for (const action of ["fetch", "reject", "reset", "fetch", "resolve"] as const) {
    phase = reduce(phase, action)
    console.log(action.padEnd(8), "→", phase)
}

