function oneOf<const T extends readonly string[]>(...allowed: T) {
    return (value: unknown): T[number] => {
        if (typeof value === "string" && (allowed as readonly string[]).includes(value)) return value as T[number]
        throw new Error(`Ruxsat etilgan qiymatlar: ${allowed.join(", ")}`)
    }
}

